func (siw *ServerInterfaceWrapper) GetSession(w http.ResponseWriter, r *http.Request) {

	handler := http.Handler(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		siw.Handler.GetSession(w, r)
	}))

	for _, middleware := range siw.HandlerMiddlewares {
		handler = middleware(handler)
	}

	handler.ServeHTTP(w, r)
}

type UnescapedCookieParamError struct {
	ParamName string
	Err       error
}

func (e *UnescapedCookieParamError) Error() string {
	return fmt.Sprintf("error unescaping cookie parameter '%s'", e.ParamName)
}

func (e *UnescapedCookieParamError) Unwrap() error {
	return e.Err
}

type UnmarshalingParamError struct {
	ParamName string
	Err       error
}

func (e *UnmarshalingParamError) Error() string {
	return fmt.Sprintf("Error unmarshaling parameter %s as JSON: %s", e.ParamName, e.Err.Error())
}

func (e *UnmarshalingParamError) Unwrap() error {
	return e.Err
}

type RequiredParamError struct {
	ParamName string
}

func (e *RequiredParamError) Error() string {
	return fmt.Sprintf("Query argument %s is required, but not found", e.ParamName)
}

type RequiredHeaderError struct {
	ParamName string
	Err       error
}

func (e *RequiredHeaderError) Error() string {
	return fmt.Sprintf("Header parameter %s is required, but not found", e.ParamName)
}

func (e *RequiredHeaderError) Unwrap() error {
	return e.Err
}

type InvalidParamFormatError struct {
	ParamName string
	Err       error
}

func (e *InvalidParamFormatError) Error() string {
	return fmt.Sprintf("Invalid format for parameter %s: %s", e.ParamName, e.Err.Error())
}

func (e *InvalidParamFormatError) Unwrap() error {
	return e.Err
}

type TooManyValuesForParamError struct {
	ParamName string
	Count     int
}

func (e *TooManyValuesForParamError) Error() string {
	return fmt.Sprintf("Expected one value for %s, got %d", e.ParamName, e.Count)
}

// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/api/v1/admin/connection", wrapper.Disconnect)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/admin/connection", wrapper.GetConnection)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/admin/connection/complete", wrapper.CompleteConnection)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/admin/connection/start", wrapper.StartConnection)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/admin/families", wrapper.ListAdminFamilies)
	m.HandleFunc(http.MethodPatch+" "+options.BaseURL+"/api/v1/admin/families/{familyId}/access", wrapper.UpdateFamilyAccess)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/admin/models", wrapper.ListModels)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/admin/settings", wrapper.GetAdminSettings)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/api/v1/admin/settings", wrapper.UpdateAdminSettings)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/families", wrapper.ListFamilies)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/families", wrapper.CreateFamily)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/api/v1/families/{familyId}/admin/conversations", wrapper.ClearConversations)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/api/v1/families/{familyId}/admin/conversations/{conversationId}", wrapper.DeleteConversation)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/api/v1/families/{familyId}/admin/dictionary", wrapper.ClearDictionary)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/api/v1/families/{familyId}/admin/dictionary/{entryId}", wrapper.DeleteDictionaryWord)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/families/{familyId}/admin/preview", wrapper.PreviewPrompt)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/families/{familyId}/admin/settings", wrapper.GetSettings)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/api/v1/families/{familyId}/admin/settings", wrapper.UpdateSettings)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/families/{familyId}/conversations", wrapper.ListConversations)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/families/{familyId}/conversations", wrapper.CreateConversation)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/families/{familyId}/conversations/{conversationId}", wrapper.GetConversation)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/families/{familyId}/conversations/{conversationId}/messages", wrapper.SendMessage)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/families/{familyId}/dictionary", wrapper.ListDictionaryWords)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/families/{familyId}/invitations", wrapper.ListInvitations)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/families/{familyId}/invitations", wrapper.CreateInvitation)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/api/v1/families/{familyId}/invitations/{invitationId}", wrapper.RevokeInvitation)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/families/{familyId}/members", wrapper.ListMembers)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/api/v1/families/{familyId}/members/{userId}", wrapper.RemoveMember)
	m.HandleFunc(http.MethodPatch+" "+options.BaseURL+"/api/v1/families/{familyId}/members/{userId}", wrapper.UpdateMember)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/families/{familyId}/status", wrapper.GetStatus)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/families/{familyId}/transcriptions", wrapper.Transcribe)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/families/{familyId}/word-images", wrapper.SearchWordImages)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/invitations/accept", wrapper.AcceptInvitation)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/logout", wrapper.Logout)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/session", wrapper.GetSession)

	return m
}

